"use strict";exports.id=4979,exports.ids=[4979],exports.modules={74979:(a,b,c)=>{c.d(b,{y:()=>d});let d=[{moduleNumber:1,moduleSlug:"module-1",title:"Introduction & Patient Workflow",emoji:"\uD83C\uDFE5",description:"Get oriented to the course, meet your instructors, and trace a patient's journey from scheduling through the healthcare revenue cycle.",lessons:[{slug:"course-overview",title:"Course Overview & Introduction",description:"Welcome to Introduction to EHR. Review course requirements, assignments, and what to expect across the semester.",duration:"15 min",videoUrl:"https://www.youtube.com/embed/OFvROse3MW4",slides:[{src:"/images/ehr/module-1/course-overview/slide-01.jpg",alt:"The Digital Clinic Blueprint — An Operational Guide to EHR Ecosystems and Clinical Patient Workflows"},{src:"/images/ehr/module-1/course-overview/slide-02.jpg",alt:"The ultimate goal of an EHR system is precise information delivery — Right Information, Right Person, Right Time"},{src:"/images/ehr/module-1/course-overview/slide-03.jpg",alt:"EHR functions as the central nervous system of healthcare operations — Patient Workflow, Healthcare Administration, Financial Management, Legal Compliance"},{src:"/images/ehr/module-1/course-overview/slide-04.jpg",alt:"Establishing a baseline vocabulary for digital healthcare infrastructure — IT vs Infrastructure, Inpatient vs Outpatient, Provider vs System"},{src:"/images/ehr/module-1/course-overview/slide-05.jpg",alt:"Seamless information flow directly correlates to systemic clinical outcomes — six operational returns including improved patient care and data security"},{src:"/images/ehr/module-1/course-overview/slide-06.jpg",alt:"The physical clinic operates across three distinct data processing zones — Front Office, Middle Office, Back Office"},{src:"/images/ehr/module-1/course-overview/slide-07.jpg",alt:"Anatomy of an EHR Specialist — Clinical Support, Administrative & Financial, Data & Compliance, Core Requirements"}],sections:[{heading:"What This Course Covers",blocks:[{type:"paragraph",text:"This course introduces you to Electronic Health Records — the digital systems that power modern healthcare. Over nine weeks you will learn patient workflow, the healthcare revenue cycle, medical coding, legal compliance, and hands-on EHR simulation using EHR Go."},{type:"list",items:["Patient registration and scheduling workflows","Healthcare revenue cycle from check-in to payment","ICD, CPT, and HCPCS coding systems","Legal and regulatory requirements for EHR use","Hands-on simulation with EHR Go"]}]},{heading:"Grading Breakdown",blocks:[{type:"list",items:["Midterm Exam — 25%","Final Exam — 25%","Participation — 25%","Homework & Lab Assignments — 25%"]},{type:"callout",variant:"info",text:"Thursday lab sessions in EHR Go count toward your Homework & Lab Assignments grade. Come prepared and log in before class starts."}]}],challenge:[{type:"knowledge-check",question:"Which component accounts for 25% of your final grade?",options:["Attendance only","Midterm Exam","Weekly quizzes","EHR Go login streak"],correctIndex:1}]},{slug:"patient-workflow-and-revenue-cycle",title:"Patient Workflow & the Healthcare Revenue Cycle",description:"Trace the path a patient takes through a healthcare encounter and learn how each step connects to the revenue cycle.",duration:"20 min",slides:[{src:"/images/ehr/module-1/patient-workflow-and-revenue-cycle/slide-01.jpg",alt:"Workflow 1: Patient Registration, Check-In, and Admission — Front Office swimlane diagram from patient arrival to rooming"},{src:"/images/ehr/module-1/patient-workflow-and-revenue-cycle/slide-02.jpg",alt:"Workflow 2: Executing the Clinical Office Visit — Nurse/Support and Provider swimlane from EHR schedule review to encounter close"},{src:"/images/ehr/module-1/patient-workflow-and-revenue-cycle/slide-03.jpg",alt:"Workflow 3: Multi-node communication for e-Prescribing during a visit — Patient, Clerk/Nurse, Prescriber, ePrescribing Network, and Pharmacy lanes"},{src:"/images/ehr/module-1/patient-workflow-and-revenue-cycle/slide-04.jpg",alt:"Workflow 4: Processing and authorizing medication refills — reverse data flow from pharmacy through network to prescriber"},{src:"/images/ehr/module-1/patient-workflow-and-revenue-cycle/slide-05.jpg",alt:"EHR transforms isolated clinical encounters into a continuous continuum of care — Patient Care, Coordination, Cost Savings, Participation, Diagnostics, Data Security"}],sections:[{heading:"The Patient Visit Lifecycle",blocks:[{type:"paragraph",text:"Every healthcare encounter follows a predictable set of steps — from scheduling to discharge to payment. Understanding this flow is the foundation of working in any healthcare administrative role."},{type:"list",ordered:!0,items:["Scheduling / Appointment Booking","Pre-Registration & Insurance Verification","Patient Check-In","Clinical Encounter (exam, procedures, orders)","Check-Out & Referrals","Coding & Charge Capture","Claim Submission","Payment Posting & Denial Management"]}]},{heading:"Why the Revenue Cycle Matters",blocks:[{type:"paragraph",text:"The revenue cycle is how a healthcare organization gets paid for the services it provides. A single error at registration — a wrong insurance ID, a misspelled name — can delay or deny payment weeks later."},{type:"callout",variant:"warning",text:"Front-end staff (registration, scheduling) directly affect back-end revenue. Accuracy at check-in prevents costly denials at billing."}]}],challenge:[{type:"knowledge-check",question:"Which step comes immediately AFTER the clinical encounter in the patient workflow?",options:["Claim submission","Insurance verification","Check-out and referrals","Payment posting"],correctIndex:2}]},{slug:"ehr-go-orientation",title:"EHR Go Lab: Orientation & Navigation",description:"Log in to EHR Go for the first time, explore the interface, and complete a guided workflow basics exercise.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"This is a hands-on lab session led by Mr. Davis. You will log in to EHR Go, navigate the dashboard, and complete the orientation activity assigned in the platform."},{type:"paragraph",text:"EHR Go is a simulated Electronic Health Record environment used by healthcare training programs nationwide. Every activity you complete in EHR Go mirrors real tasks performed in clinic and hospital settings."}]},{heading:"Lab Objectives",blocks:[{type:"list",items:["Log in to EHR Go with your assigned credentials","Navigate the main dashboard and menu structure","Identify key areas: patient search, scheduling, documentation","Complete the EHR Go orientation activity"]}]}]}],level:"Beginner",estimatedMinutes:115,whatYoullLearn:["Course structure, grading, and expectations","The full patient workflow lifecycle in a healthcare setting","Key steps in the healthcare revenue cycle","How to navigate EHR Go for the first time"],scenario:"You just started as an administrative support specialist at Brooklyn Community Health Center. On Day 1, your supervisor walks you through how a patient flows from the waiting room through billing. By Thursday, you are logging in to EHR Go for the first time."},{moduleNumber:2,moduleSlug:"module-2",title:"Revenue Cycle & ICD Coding",emoji:"\uD83D\uDCB0",description:"Deepen your understanding of revenue cycle management, clinical preauthorization, and begin learning ICD-10-CM diagnostic coding.",lessons:[{slug:"revenue-cycle-and-preauthorization",title:"Revenue Cycle Management & Clinical Preauthorization",description:"Dive deeper into revenue cycle management and learn how clinical preauthorization protects both patients and providers.",duration:"20 min",sections:[{heading:"Revenue Cycle Management (RCM) Deep Dive",blocks:[{type:"paragraph",text:"Revenue Cycle Management is the financial process healthcare organizations use to track patient care episodes from registration to final payment. Effective RCM minimizes claim denials and maximizes reimbursement."},{type:"list",items:["Patient access (registration, eligibility, benefits verification)","Health information management (coding, documentation)","Patient financial services (billing, collections)","Claims management (submission, follow-up, appeals)"]}]},{heading:"Clinical Preauthorization",blocks:[{type:"paragraph",text:"Preauthorization (also called prior authorization) is the process of getting insurance approval before a patient receives certain procedures, medications, or specialist referrals."},{type:"callout",variant:"warning",text:"Skipping preauthorization when it is required can result in a denied claim — meaning the provider may not get paid and the patient could be billed unexpectedly."}]}],challenge:[{type:"knowledge-check",question:"What is the primary purpose of clinical preauthorization?",options:["To schedule appointments faster","To obtain insurance approval before delivering a service","To verify a patient's identity at check-in","To assign ICD codes to a diagnosis"],correctIndex:1}]},{slug:"medical-coding-icd-part-1",title:"Medical Coding Overview: ICD Part 1",description:"Introduction to the International Classification of Diseases (ICD) coding system and its role in healthcare billing.",duration:"25 min",sections:[{heading:"What Is ICD Coding?",blocks:[{type:"paragraph",text:"ICD stands for International Classification of Diseases. It is the global standard for classifying diagnoses, symptoms, and health conditions. In the United States, ICD-10-CM is used for outpatient and physician billing."},{type:"list",items:["ICD-10-CM: Clinical Modification — used by providers to code diagnoses","ICD-10-PCS: Procedure Coding System — used in inpatient hospital settings","Codes are alphanumeric (e.g., J18.9 = Pneumonia, unspecified)"]}]},{heading:"Why Accurate ICD Coding Matters",blocks:[{type:"paragraph",text:"ICD codes are used on every insurance claim. An inaccurate code can cause a claim to be rejected, underpaid, or flagged for audit. Coders must select the most specific code that is supported by documentation."},{type:"callout",variant:"info",text:"The rule in coding: if it isn't documented, it didn't happen. Coders cannot assign a code for a condition that the provider did not document in the patient record."}]}],challenge:[{type:"knowledge-check",question:"Which ICD version is used in the United States for outpatient diagnosis coding?",options:["ICD-9-CM","ICD-10-PCS","ICD-10-CM","ICD-11"],correctIndex:2}]},{slug:"patient-registration-insurance-review-lab",title:"EHR Go Lab: Patient Registration & Insurance Review",description:"Practice front-end workflow in EHR Go by registering a new patient, entering insurance information, and verifying eligibility.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"In this lab session, Mr. Davis will guide you through patient registration and insurance review workflows in EHR Go."},{type:"list",items:["Register a new patient in EHR Go","Enter primary and secondary insurance information","Verify patient eligibility through the EHR Go simulation","Review common front-end errors that cause billing denials"]}]}]}],level:"Beginner",estimatedMinutes:125,whatYoullLearn:["Revenue cycle management — front-end to back-end","What clinical preauthorization is and when it is required","How ICD-10-CM codes are structured and used","Why accurate diagnosis coding is critical to reimbursement"],scenario:"A patient is scheduled for an MRI but needs preauthorization first. Your clinic's billing office receives a denial because the ICD code on the original request was too general. You are asked to help identify the correct, specific code."},{moduleNumber:3,moduleSlug:"module-3",title:"Diagnostic & Procedural Coding",emoji:"\uD83D\uDDC2️",description:"Expand your coding skills with ICD-10-CM specificity, CPT procedure codes, modifiers, and how diagnoses link to procedures on a claim.",lessons:[{slug:"icd-part-2-and-cpt-part-1",title:"Diagnostic Coding (ICD Part 2) & CPT Introduction",description:"Continue developing ICD-10-CM skills and begin learning Current Procedural Terminology (CPT) coding for outpatient procedures.",duration:"25 min",sections:[{heading:"ICD-10-CM: Code Structure Review",blocks:[{type:"paragraph",text:"ICD-10-CM codes can be 3–7 characters long. The first three characters identify the category of disease. Additional characters add specificity — laterality, encounter type, sequela, and more."},{type:"list",items:["Characters 1–3: Category (e.g., S52 = Fracture of forearm)","Character 4: Etiology, anatomic site, or severity","Characters 5–6: Further specificity","Character 7: Extension (A = initial, D = subsequent, S = sequela)"]}]},{heading:"Introduction to CPT Coding",blocks:[{type:"paragraph",text:"CPT (Current Procedural Terminology) codes are five-digit numeric codes maintained by the American Medical Association (AMA). They describe the medical, surgical, and diagnostic services performed during an encounter."},{type:"list",items:["Evaluation & Management (E/M): 99202–99215","Surgery codes: 10000–69999","Radiology: 70000–79999","Pathology & Laboratory: 80000–89999","Medicine: 90000–99199"]}]}],challenge:[{type:"knowledge-check",question:"Which organization maintains the CPT code set?",options:["Centers for Medicare & Medicaid Services (CMS)","World Health Organization (WHO)","American Medical Association (AMA)","American Health Information Management Association (AHIMA)"],correctIndex:2}]},{slug:"cpt-part-2",title:"Current Procedural Coding (CPT) Part 2",description:"Deepen your CPT knowledge with modifiers, bundling rules, and how CPT codes link to ICD codes on a claim.",duration:"25 min",sections:[{heading:"CPT Modifiers",blocks:[{type:"paragraph",text:"Modifiers are two-character additions to a CPT code that provide additional information about a service without changing its definition. They affect how a claim is processed and reimbursed."},{type:"list",items:["-25: Significant, separately identifiable E/M service on the same day","-51: Multiple procedures","-59: Distinct procedural service","-RT / -LT: Right side / Left side"]}]},{heading:"Linking Diagnoses to Procedures",blocks:[{type:"paragraph",text:"Every CPT code on a claim must be linked to at least one ICD-10-CM diagnosis code that justifies medical necessity. If the diagnosis does not support the procedure, the claim will be denied."},{type:"callout",variant:"warning",text:"Medical necessity is the cornerstone of claims approval. The diagnosis must clearly explain why the procedure was performed."}]}],challenge:[{type:"knowledge-check",question:"What does CPT modifier -25 indicate?",options:["The procedure was performed on the left side of the body","Multiple procedures were performed on the same day","A significant, separately identifiable E/M service was provided on the same day as a procedure","The service was performed by a physician assistant"],correctIndex:2}]},{slug:"outpatient-coding-and-payments-lab",title:"EHR Go Lab: Outpatient Coding Workflow & Payment Posting",description:"Practice entering outpatient diagnosis and procedure codes in EHR Go, then post a payment and apply an adjustment.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"In this lab, Mr. Davis will guide you through the coding and payment posting workflow in EHR Go using a simulated patient encounter."},{type:"list",items:["Assign ICD-10-CM diagnosis codes to a patient encounter","Select appropriate CPT procedure codes","Submit a simulated claim in EHR Go","Post an insurance payment and apply a contractual adjustment"]}]}]}],level:"Beginner",estimatedMinutes:130,whatYoullLearn:["ICD-10-CM code structure — characters, extensions, and specificity","CPT code categories and how they describe healthcare services","How modifiers affect claim processing and reimbursement","How to link a diagnosis code to a procedure code for medical necessity"],scenario:"A provider saw a patient for a sprained left ankle (initial encounter) and ordered an X-ray. You need to assign the correct ICD code with proper laterality and encounter extension, then link it to the correct CPT radiology code before the claim goes out."},{moduleNumber:4,moduleSlug:"module-4",title:"HCPCS & Midterm Preparation",emoji:"\uD83D\uDCCB",description:"Learn HCPCS Level II coding for equipment, drugs, and supplies — then review all concepts in preparation for the midterm exam.",lessons:[{slug:"introduction-to-hcpcs",title:"Introduction to Healthcare Procedure Coding (HCPCS)",description:"Learn the HCPCS Level II coding system used for supplies, equipment, medications, and services not covered by CPT.",duration:"20 min",sections:[{heading:"What Is HCPCS?",blocks:[{type:"paragraph",text:"HCPCS (Healthcare Common Procedure Coding System) is a standardized coding system maintained by CMS. It has two levels:"},{type:"list",items:["Level I: CPT codes (American Medical Association) — physician services and procedures","Level II: Alphanumeric codes (A0000–V9999) — ambulance, durable medical equipment, drugs, and supplies not covered in CPT"]}]},{heading:"Common HCPCS Level II Categories",blocks:[{type:"list",items:["A codes: Transportation, medical/surgical supplies","E codes: Durable medical equipment (wheelchairs, crutches, oxygen)","J codes: Drugs administered other than by oral method","L codes: Orthotic and prosthetic procedures"]},{type:"callout",variant:"info",text:"Medicare and Medicaid require HCPCS Level II codes for many services that CPT does not cover. Knowing when to use HCPCS vs. CPT is a key billing skill."}]}],challenge:[{type:"knowledge-check",question:"Which HCPCS Level II code category covers durable medical equipment like wheelchairs?",options:["A codes","J codes","E codes","L codes"],correctIndex:2}]},{slug:"midterm-review",title:"Course Review & Midterm Exam Preparation",description:"Review all major concepts from Weeks 1–4 in preparation for the midterm exam.",duration:"25 min",sections:[{heading:"Topics Covered on the Midterm",blocks:[{type:"list",items:["Patient workflow steps from scheduling through payment","Healthcare revenue cycle — front-end and back-end","ICD-10-CM diagnosis coding basics","CPT procedure coding and modifiers","HCPCS Level II code categories","Clinical preauthorization process"]},{type:"callout",variant:"success",text:"The midterm includes multiple choice, true/false, and short answer questions. Review your notes, textbook chapters, and EHR Go lab activities."}]}]},{slug:"midterm-skills-review-lab",title:"EHR Go Lab: Midterm Skills Review",description:"Hands-on review of registration, insurance verification, coding workflow, and documentation in EHR Go before the midterm.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"This lab is a comprehensive skills review across all EHR Go activities completed so far. Mr. Davis will walk through each workflow and answer questions before the midterm."},{type:"list",items:["Patient registration and insurance entry review","Coding a simulated encounter (ICD + CPT)","Payment posting and adjustment review","Q&A and clarification on midterm topics"]}]}]}],level:"Beginner",estimatedMinutes:125,whatYoullLearn:["HCPCS Level II code categories and when to use them","The difference between CPT and HCPCS Level II","How Medicare and Medicaid use HCPCS codes","All midterm topics: workflow, revenue cycle, ICD, CPT, and HCPCS"],scenario:"A patient is discharged with a wheelchair (E-code) and a home oxygen setup (E-code). The clinic also administered an injectable medication (J-code). You must select the correct HCPCS codes for all three items before the claim is submitted."},{moduleNumber:5,moduleSlug:"module-5",title:"Midterm & Patient-Centered Care",emoji:"\uD83D\uDCDD",description:"Take the midterm exam, then explore patient-centered medical home models and Computerized Provider Order Entry (CPOE).",lessons:[{slug:"midterm-exam",title:"Midterm Exam",description:"Assessment covering patient workflow, revenue cycle, ICD, CPT, and HCPCS coding concepts from Weeks 1–4.",duration:"80 min",sections:[{heading:"Exam Information",blocks:[{type:"callout",variant:"info",text:"The midterm exam is administered in class by Mr. Gera. It includes multiple choice, true/false, and short answer sections covering all material from Weeks 1–4."},{type:"paragraph",text:"The midterm counts for 25% of your final grade. Make sure you have reviewed the Week 4 study materials and completed the EHR Go midterm skills review lab."}]}]},{slug:"patient-centered-care-and-cpoe-part-1",title:"Patient-Centered Medical Home, FQHC & CPOE Part 1",description:"Explore patient-centered care models and begin learning Computerized Provider Order Entry (CPOE) systems.",duration:"25 min",sections:[{heading:"Patient-Centered Medical Home (PCMH)",blocks:[{type:"paragraph",text:"The Patient-Centered Medical Home is a care delivery model that coordinates comprehensive primary care across specialties and settings. It emphasizes continuous, coordinated care and patient engagement."},{type:"list",items:["Accessible, team-based primary care","Whole-person approach to health","Coordinated referrals and follow-up","Quality measurement and improvement"]}]},{heading:"Federally Qualified Health Centers (FQHCs)",blocks:[{type:"paragraph",text:"FQHCs are community-based healthcare providers that receive federal funding to provide primary care in underserved areas. They must demonstrate use of EHR systems and follow specific billing rules under Medicare and Medicaid."}]},{heading:"Introduction to CPOE",blocks:[{type:"paragraph",text:"Computerized Provider Order Entry (CPOE) allows clinicians to enter medical orders directly into the EHR system, replacing handwritten orders. CPOE reduces medication errors and improves workflow efficiency."},{type:"callout",variant:"success",text:"CPOE is a key Meaningful Use / Promoting Interoperability requirement. Hospitals must demonstrate CPOE use to qualify for CMS incentive programs."}]}],challenge:[{type:"knowledge-check",question:"What is the primary benefit of Computerized Provider Order Entry (CPOE)?",options:["It replaces the need for insurance verification","It allows patients to order their own lab tests","It reduces medication errors by eliminating handwritten orders","It automates claim submission to insurance companies"],correctIndex:2}]},{slug:"provider-order-entry-lab",title:"EHR Go Lab: Provider Order Entry & Patient Chart Review",description:"Use EHR Go to enter simulated provider orders, complete documentation tasks, and review a patient chart.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"Mr. Davis leads this hands-on lab focused on CPOE and clinical documentation in EHR Go."},{type:"list",items:["Navigate to the order entry section of EHR Go","Enter a simulated lab order and medication order","Complete a clinical documentation task","Review a completed patient chart for accuracy"]}]}]}],level:"Intermediate",estimatedMinutes:125,whatYoullLearn:["Demonstrate competency through the midterm assessment","Patient-Centered Medical Home and FQHC care models","What CPOE is and why it reduces medication errors","How to enter provider orders in EHR Go"],scenario:"After the midterm, your supervisor introduces you to the clinic's CPOE system. A provider orders a medication but there is a duplicate alert — the patient is already on that drug. You learn how Clinical Decision Support helps catch errors before they reach the patient."},{moduleNumber:6,moduleSlug:"module-6",title:"Legal Aspects & HIPAA Compliance",emoji:"⚖️",description:"Study CPOE in depth, then master HIPAA, patient privacy rights, and the legal framework governing Electronic Health Records.",lessons:[{slug:"cpoe-part-2",title:"Computerized Provider Order Entry (CPOE) Part 2",description:"Continue CPOE study with advanced order sets, clinical decision support, and how CPOE integrates with EHR workflows.",duration:"20 min",sections:[{heading:"Order Sets & Clinical Decision Support",blocks:[{type:"paragraph",text:"Most EHR systems include pre-built order sets — groups of orders commonly used together for specific diagnoses or procedures. Clinical Decision Support (CDS) alerts notify providers of potential drug interactions, allergies, or guideline deviations."},{type:"list",items:["Order sets speed up order entry and reduce omissions","CDS alerts promote evidence-based prescribing","Alert fatigue is a known challenge — too many alerts get ignored"]}]},{heading:"CPOE Workflow Integration",blocks:[{type:"paragraph",text:"When a provider enters an order through CPOE, it is immediately transmitted to the appropriate department — pharmacy, radiology, lab — without requiring paper transport. This reduces delays and transcription errors."},{type:"callout",variant:"success",text:"Studies show CPOE reduces serious medication errors by more than 50% compared to handwritten orders."}]}],challenge:[{type:"knowledge-check",question:"What is a known downside of Clinical Decision Support alerts?",options:["They slow down CPOE order entry by requiring fax confirmation","Alert fatigue — providers begin ignoring alerts when there are too many","They are only available in inpatient hospital EHR systems","CDS alerts cannot detect drug allergies"],correctIndex:1}]},{slug:"legal-aspects-and-compliance",title:"Legal Aspects of EHR & Regulatory Compliance",description:"Understand HIPAA, patient privacy rights, legal obligations in EHR environments, and consequences of non-compliance.",duration:"25 min",sections:[{heading:"HIPAA and Protected Health Information",blocks:[{type:"paragraph",text:"HIPAA (Health Insurance Portability and Accountability Act) sets national standards for protecting sensitive patient health information. The Privacy Rule and Security Rule are the two most relevant components for EHR users."},{type:"list",items:["Privacy Rule: Controls who can access and use PHI (Protected Health Information)","Security Rule: Sets standards for protecting electronic PHI (ePHI)","Breach Notification Rule: Requires notification of affected patients if PHI is breached"]}]},{heading:"Penalties for Non-Compliance",blocks:[{type:"list",items:["Civil penalties: $100–$50,000 per violation","Criminal penalties: Up to 10 years imprisonment for intentional misuse","Reputational damage to the healthcare organization"]},{type:"callout",variant:"warning",text:"Accessing a patient record without a legitimate reason — even for curiosity — is a HIPAA violation. Always access only the records needed for your assigned duties."}]}],challenge:[{type:"knowledge-check",question:"Which HIPAA rule sets standards for protecting electronic Protected Health Information (ePHI)?",options:["The Privacy Rule","The Security Rule","The Breach Notification Rule","The Enforcement Rule"],correctIndex:1}]},{slug:"compliance-scenarios-lab",title:"EHR Go Lab: Documentation Accuracy, Privacy & Compliance Scenarios",description:"Work through privacy and compliance scenarios in EHR Go, focusing on accurate clinical documentation and HIPAA-compliant behavior.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"Mr. Davis guides this lab through EHR Go scenarios that test documentation accuracy, appropriate record access, and privacy-compliant workflows."},{type:"list",items:["Identify documentation errors in a sample patient record","Apply HIPAA minimum necessary standard in a simulated scenario","Complete an EHR Go compliance-focused activity","Discuss real-world consequences of documentation failures"]}]}]}],level:"Intermediate",estimatedMinutes:125,whatYoullLearn:["Advanced CPOE concepts — order sets and alert fatigue","HIPAA Privacy Rule and Security Rule","Patient rights under HIPAA (access, amendment, accounting of disclosures)","Penalties for HIPAA violations and real-world compliance scenarios"],scenario:"A coworker asks you to pull up a patient record for someone they know personally. You immediately recognize this as a potential HIPAA violation. This module teaches you exactly why — and what to do instead."},{moduleNumber:7,moduleSlug:"module-7",title:"EHR Databases & Financial Management",emoji:"\uD83D\uDDC4️",description:"Review core workflows, then explore how EHR databases support patient tracking, clinical administration, and financial management.",lessons:[{slug:"workflow-and-revenue-cycle-review",title:"Workflow, Revenue Cycle & CPOE Review",description:"Comprehensive review of patient workflow, revenue cycle management, clinical preauthorization, and CPOE before tackling advanced topics.",duration:"20 min",sections:[{heading:"Key Concepts Review",blocks:[{type:"paragraph",text:"Before moving into EHR databases and financial management, let's consolidate the core workflows you've studied so far."},{type:"list",items:["Patient workflow: scheduling → registration → encounter → coding → billing","Revenue cycle: front-end (access) → mid-cycle (coding) → back-end (billing/collections)","Preauthorization: required for certain procedures, medications, and specialist referrals","CPOE: electronic order entry reducing medication errors and improving communication"]},{type:"callout",variant:"success",text:"These concepts are interconnected. A gap in any step of the workflow — registration error, coding mistake, or missing preauth — creates downstream revenue problems."}]}],challenge:[{type:"knowledge-check",question:"Which phase of the revenue cycle involves submitting claims to insurance payers?",options:["Front-end / Patient Access","Mid-cycle / Health Information Management","Back-end / Patient Financial Services","Clinical Decision Support"],correctIndex:2}]},{slug:"ehr-databases-patient-tracking",title:"EHR Databases for Patient Tracking & Financial Management",description:"Understand how EHR databases support patient tracking, clinical administration, and financial management functions.",duration:"25 min",sections:[{heading:"EHR as a Database System",blocks:[{type:"paragraph",text:"An Electronic Health Record system is fundamentally a database — it stores, retrieves, and connects patient data across clinical, administrative, and financial domains."},{type:"list",items:["Patient master index: maintains unique patient identification across the organization","Appointment and scheduling databases: track provider availability and patient visits","Clinical data repositories: store lab results, imaging, and documentation","Financial databases: support charge capture, billing, and accounts receivable"]}]},{heading:"Using EHR Data for Financial Management",blocks:[{type:"paragraph",text:"EHR systems generate financial reports that help organizations monitor revenue, identify billing bottlenecks, and track accounts receivable aging. Understanding these reports is valuable for administrative staff."},{type:"list",items:["Days in A/R: how long it takes to collect payment after a claim is submitted","Denial rate: percentage of claims denied by payers","Clean claim rate: percentage of claims paid on first submission"]}]}],challenge:[{type:"knowledge-check",question:"What does 'Days in A/R' measure in healthcare financial management?",options:["The number of days a patient waits for an appointment","How long it takes to collect payment after a claim is submitted","The number of days a provider works per week","How many days a claim can be appealed"],correctIndex:1}]},{slug:"patient-tracking-financial-management-lab",title:"EHR Go Lab: Patient Tracking, Administrative & Financial Workflows",description:"Apply patient tracking and financial management concepts in EHR Go through structured exercises.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"Mr. Davis leads this lab through EHR Go's administrative and financial management features."},{type:"list",items:["Search and track patients across the EHR Go system","Run a basic financial report in the simulation","Review an accounts receivable aging summary","Identify and document a sample claim status"]}]}]}],level:"Intermediate",estimatedMinutes:125,whatYoullLearn:["Consolidated review of patient workflow, revenue cycle, and CPOE","How EHR systems function as clinical and financial databases","Key financial metrics: Days in A/R, denial rate, clean claim rate","How to use EHR Go's administrative and financial tracking features"],scenario:"Your administrator asks why the clinic's accounts receivable has been climbing for three months. You pull a Days in A/R report from EHR Go and identify that a specific payer is consistently taking 45+ days to pay. This module shows you how to find and interpret that data."},{moduleNumber:8,moduleSlug:"module-8",title:"Advanced Legal Topics & Integrated Practice",emoji:"\uD83D\uDD12",description:"Explore the legal landscape governing EHR beyond HIPAA, learn clinical data analysis concepts, and complete an integrated capstone case.",lessons:[{slug:"legal-aspects-and-clinical-data-analysis",title:"Legal Aspects of EHR & Clinical Data Analysis",description:"Explore the legal framework governing EHR use and how clinical data is analyzed to support quality improvement and compliance.",duration:"25 min",sections:[{heading:"Legal Aspects of the EHR Environment",blocks:[{type:"paragraph",text:"Beyond HIPAA, the EHR environment is shaped by federal and state laws governing health information, data retention, release of information, and electronic signatures."},{type:"list",items:["HITECH Act: Expanded HIPAA enforcement and introduced Meaningful Use","21st Century Cures Act: Prohibits information blocking and promotes interoperability","State retention laws: Define how long records must be kept (typically 6–10 years)","Electronic signatures: Legally valid when systems meet specific authentication standards"]}]},{heading:"Clinical Data Analysis",blocks:[{type:"paragraph",text:"Healthcare organizations use clinical data to identify trends, improve outcomes, and meet regulatory reporting requirements. EHR systems are the primary source for this data."},{type:"list",items:["Quality measure reporting (HEDIS, CMS Star Ratings)","Population health management — identifying high-risk patients","Clinical audit — reviewing records for documentation completeness","Research and public health surveillance"]},{type:"callout",variant:"info",text:"Administrative staff play a role in data quality. Accurate registration, coding, and documentation directly impact the validity of clinical data analysis."}]}],challenge:[{type:"knowledge-check",question:"Which federal law prohibits healthcare organizations from blocking the flow of health information?",options:["HIPAA Privacy Rule","HITECH Act","21st Century Cures Act","Affordable Care Act"],correctIndex:2}]},{slug:"regulatory-compliance-and-revenue-cycle",title:"Healthcare Regulatory Compliance & the Revenue Cycle",description:"Connect regulatory compliance requirements to revenue cycle operations and understand the consequences of non-compliant billing.",duration:"25 min",sections:[{heading:"Compliance Programs in Healthcare",blocks:[{type:"paragraph",text:"Healthcare organizations are required to maintain formal compliance programs that prevent, detect, and correct violations of applicable laws and regulations."},{type:"list",items:["OIG (Office of Inspector General) compliance guidance","False Claims Act — penalties for knowingly submitting fraudulent claims","Anti-Kickback Statute — prohibits payment for referrals","Stark Law — prohibits physician self-referral for designated health services"]}]},{heading:"Compliance and the Revenue Cycle",blocks:[{type:"paragraph",text:"Billing compliance means that every claim submitted accurately reflects the services documented in the patient record. Upcoding, unbundling, and billing for services not rendered are all forms of fraud."},{type:"callout",variant:"warning",text:"The False Claims Act allows the government to recover three times the amount of a fraudulent claim plus additional penalties per claim. Healthcare fraud is taken seriously."}]}],challenge:[{type:"knowledge-check",question:"What is 'upcoding' in healthcare billing?",options:["Using a higher-level code than what the documentation supports to receive more reimbursement","Submitting a claim to a secondary insurer after the primary payer pays","Entering multiple CPT codes for a single procedure","Updating a patient's insurance information after a denial"],correctIndex:0}]},{slug:"integrated-case-practice-lab",title:"EHR Go Lab: Integrated Case Practice",description:"Complete an integrated case in EHR Go covering revenue cycle, compliance, and documentation from registration through payment posting.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"info",text:"This is a capstone lab session. Mr. Davis will guide you through a full patient encounter from registration to payment posting using EHR Go."},{type:"list",items:["Register a new patient and verify insurance eligibility","Document the clinical encounter and assign diagnosis and procedure codes","Submit a simulated claim and track its status","Post the payment and resolve a sample denial"]}]}]}],level:"Intermediate",estimatedMinutes:130,whatYoullLearn:["HITECH Act, 21st Century Cures Act, and record retention requirements","How clinical data is used for quality reporting and population health","Healthcare billing compliance — False Claims Act, Stark Law, Anti-Kickback","Full revenue cycle simulation from registration through payment posting"],scenario:"Your clinic receives an OIG audit notice. You work with the compliance officer to review recent claims for potential upcoding or documentation gaps. This module teaches you what auditors look for — and how to keep your work audit-proof."},{moduleNumber:9,moduleSlug:"module-9",title:"Final Exam & CEHRS Certification Prep",emoji:"\uD83C\uDF93",description:"Complete the final exam, prepare for the NHA Certified EHR Specialist (CEHRS) exam, and wrap up with a final hands-on EHR Go competency review.",lessons:[{slug:"final-exam",title:"Course Final Exam",description:"Cumulative assessment covering all course material including patient workflow, coding, compliance, CPOE, and EHR fundamentals.",duration:"80 min",sections:[{heading:"Exam Information",blocks:[{type:"callout",variant:"info",text:"The final exam is administered in class by Mr. Gera. It is cumulative and covers all material from Weeks 1–8. It includes multiple choice, true/false, and short answer questions."},{type:"paragraph",text:"The final exam counts for 25% of your final grade. Review all previous modules, your EHR Go lab notes, and the midterm feedback from your instructor."}]}]},{slug:"nha-cehrs-exam-prep",title:"NHA Certified EHR Specialist (CEHRS) Exam Preparation",description:"Prepare for the NHA CEHRS certification exam with a review of exam content domains, test-taking strategies, and practice questions.",duration:"25 min",sections:[{heading:"About the NHA CEHRS Exam",blocks:[{type:"paragraph",text:"The NHA (National Healthcareer Association) Certified Electronic Health Records Specialist (CEHRS) exam validates competency in EHR systems, healthcare data management, and administrative workflows."},{type:"list",items:["Exam format: 110 questions (100 scored + 10 pretest)","Time limit: 3 hours","Delivery: Computer-based at an approved testing site or remotely proctored","Passing score: 390 out of 500"]}]},{heading:"CEHRS Content Domains",blocks:[{type:"list",items:["EHR Functions and Workflows (~22%)","Data Management and Entry (~20%)","Revenue Cycle Management (~18%)","Legal and Ethical Aspects (~16%)","Patient Communication and Education (~12%)","Health Informatics and Technology (~12%)"]},{type:"callout",variant:"success",text:"Everything covered in this course maps directly to CEHRS content domains. Strong performance in this course puts you on the right track for certification."}]}],challenge:[{type:"knowledge-check",question:"What is the passing score for the NHA CEHRS exam?",options:["70 out of 100","390 out of 500","100 out of 110","450 out of 500"],correctIndex:1}]},{slug:"final-hands-on-review-lab",title:"EHR Go Lab: Final Hands-On Review & Course Wrap-Up",description:"Complete a final competency check in EHR Go and celebrate your progress through the Introduction to EHR course.",duration:"80 min",sections:[{heading:"Lab Overview",blocks:[{type:"callout",variant:"success",text:"Congratulations on completing the Introduction to EHR course. This final lab session is your opportunity to demonstrate competency and get feedback from Mr. Davis."},{type:"list",items:["Complete the EHR Go final competency activity","Receive feedback on your simulation performance","Review CEHRS exam registration steps","Course wrap-up and next steps discussion"]}]}]}],level:"Advanced",estimatedMinutes:185,whatYoullLearn:["Demonstrate mastery through the cumulative final exam","NHA CEHRS exam format, content domains, and passing requirements","Test-taking strategies for the CEHRS certification","Complete a final EHR Go competency activity"],scenario:"You have completed Introduction to EHR. You sit for the final exam, then turn your attention to the NHA CEHRS certification — your credential for entering the healthcare workforce as a recognized Electronic Health Records Specialist."}]}};